for _ in range(int(input())):
	s = input()
	n = len(s)
	a = s.count('A')
	b = s.count('B')
	c = 0
	if a > 2 and b == 0 or (b > 2 and a == 0):
		print(-1)
		c = 1
	elif a == 2:
		print('A')
		c = 1
	elif b == 2:
		print('B')
		c = 1
	elif n > 3:
		for i in range(n - 3):
			if i == 0 and (s[:3] == 'AAB' or s[:4] == 'BBA'):
				print(s[1:])
				c = 1
				break
			else:
				p = s[i:i + 4]
				if p == 'ABBA' or p == 'BAAB':
					print(s[:i + 1] + s[i + 2:])
					c = 1
					break
		if c == 0 and (s[n - 3:] == 'ABB' or s[n - 3:] == 'BAA'):
			print(s[:n - 1])
			c = 1
	if c == 0:
		print(-1)
